// Pure core of app lock: PIN hashing rules and attempt/cooldown math.
// No expo imports so `bun test` can cover hash/verify and wrong-PIN
// rejection without a device.

const MAX_SALT_ASCII = 32;

/** Cryptographically random hex salt, generated by expo-crypto on device. */
export function randomSaltHex(byteLength = 16): string {
  // Shared Math.random fallback is only for tests; the device path uses
  // `getRandomBytes` from expo-crypto (see lib/app-lock.ts).
  let hex = "";
  for (let i = 0; i < byteLength * 2; i += 1) {
    hex += Math.floor(Math.random() * 16).toString(16);
  }
  return hex;
}

/** salt + PIN -> hex digest. On device `hashPinAsync` uses expo-crypto. */
export function combineForHash(salt: string, pin: string): string {
  return `${salt}:${pin}`;
}

export interface PinRecord {
  salt: string;
  hash: string;
}

export interface LockConfig {
  /** Auto-lock delay in milliseconds; default 60s per the design. */
  autoLockMs: number;
}

export const DEFAULT_LOCK_CONFIG: LockConfig = { autoLockMs: 60_000 };

export const MAX_PIN_LENGTH = 6;
export const MIN_PIN_LENGTH = 4;

export function isValidPin(pin: string): boolean {
  return new RegExp(`^\\d{${MIN_PIN_LENGTH},${MAX_PIN_LENGTH}}$`).test(pin);
}

/** Consecutive failures before the cooldown begins. */
export const COOLDOWN_THRESHOLD = 5;

/**
 * Cooldown in milliseconds after the nth consecutive failure. From the fifth
 * failure the delay grows exponentially: 30s, 60s, 120s, ...
 */
export function cooldownMs(consecutiveFailures: number): number {
  if (consecutiveFailures < COOLDOWN_THRESHOLD) return 0;
  const exp = consecutiveFailures - COOLDOWN_THRESHOLD;
  return 30_000 * 2 ** exp;
}

export interface AttemptState {
  consecutiveFailures: number;
  lockedUntil: number | null;
}

export function recordFailure(state: AttemptState, now: number): AttemptState {
  const consecutiveFailures = state.consecutiveFailures + 1;
  const delay = cooldownMs(consecutiveFailures);
  return {
    consecutiveFailures,
    lockedUntil: delay > 0 ? now + delay : null,
  };
}

export function isLocked(state: AttemptState, now: number): boolean {
  return state.lockedUntil !== null && state.lockedUntil > now;
}

/** Should the auto-lock timer re-lock, given backgrounded-at timestamps? */
export function shouldRelock(
  backgroundedAtMs: number | null,
  nowMs: number,
  config: LockConfig = DEFAULT_LOCK_CONFIG,
): boolean {
  if (backgroundedAtMs === null) return false;
  return nowMs - backgroundedAtMs >= config.autoLockMs;
}

export { MAX_SALT_ASCII };
